CREATE   PROCEDURE studio.spStoredDatasetCreate     @Payload nvarchar(max) AS BEGIN  SET NOCOUNT ON;  IF ISJSON(@Payload) <> 1 BEGIN SELECT CAST(0 AS bit) success, 'DATASET_INPUT_INVALID' code; RETURN; END;  DECLARE @UserID uniqueidentifier=TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Payload,'$.UserID')),          @ConnectionID uniqueidentifier=TRY_CONVERT(uniqueidentifier,JSON_VALUE(@Payload,'$.ConnectionID')),          @Name nvarchar(150)=NULLIF(LTRIM(RTRIM(JSON_VALUE(@Payload,'$.DatasetName'))),''),          @Description nvarchar(1000)=JSON_VALUE(@Payload,'$.Description'),          @Schema sysname=JSON_VALUE(@Payload,'$.SourceSchema'),          @Source sysname=JSON_VALUE(@Payload,'$.SourceName'),          @Type varchar(20)=JSON_VALUE(@Payload,'$.SourceType');  IF @UserID IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.core_user WHERE user_id=@UserID AND is_active=1 AND is_locked=0)  BEGIN SELECT CAST(0 AS bit) success,'USER_UNAVAILABLE' code; RETURN; END;  IF @Name IS NULL OR @Schema IS NULL OR @Source IS NULL OR @Type NOT IN ('BASE TABLE','VIEW')     OR @ConnectionID IS NULL OR NOT EXISTS (SELECT 1 FROM studio.connection WHERE connection_id=@ConnectionID AND is_active=1)   BEGIN SELECT CAST(0 AS bit) success,'DATASET_INPUT_INVALID' code; RETURN; END;  BEGIN TRY   BEGIN TRANSACTION; DECLARE @DatasetID uniqueidentifier=NEWID();   INSERT studio.dataset(dataset_id,dataset_name,description,connection_id,source_schema,source_name,source_type,access_mode,storage_status,created_by)   VALUES(@DatasetID,@Name,@Description,@ConnectionID,@Schema,@Source,@Type,'STORED','PENDING',CONVERT(nvarchar(100),@UserID));
    /* PHASE2D3_ATOMIC_OWNERSHIP */
    INSERT INTO studio.object_ownership(object_type,object_id,owner_user_id)
    VALUES ('DATASET',@DatasetID,@UserID);
    INSERT INTO studio.object_access_audit(actor_user_id,object_type,object_id,action_type,new_owner_user_id)
    VALUES (@UserID,'DATASET',@DatasetID,'REGISTER',@UserID);
 COMMIT TRANSACTION;   SELECT CAST(1 AS bit) success,'DATASET_CREATED' code,CONVERT(varchar(36),@DatasetID) dataset_id;  END TRY  BEGIN CATCH   IF @@TRANCOUNT>0 ROLLBACK TRANSACTION; SELECT CAST(0 AS bit) success, CASE WHEN ERROR_NUMBER() IN (2601,2627) THEN 'DATASET_DUPLICATE' ELSE 'DATASET_CREATE_FAILED' END code;  END CATCH; END; 